insert into public.worksheet_versions(id,worksheet_id,version_number,school_year,content_json) values('5c38eb79-de28-5a33-aa9a-542e7b17ebef','607661d9-6bbd-583a-9c7b-2c3d5d4ba4f7',1,3,'{"instructions":"Lê com atenção e responde ao teu ritmo. Nas perguntas abertas, explica o teu raciocínio.","questions":[{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. Qual era o assunto do livro procurado?","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q1","options":[{"id":"a","text":"Os oceanos"},{"id":"b","text":"As montanhas"},{"id":"c","text":"Os planetas"}],"correctAnswer":"a"},{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. Por que procurou esse livro?","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q2","options":[{"id":"a","text":"Para aprender uma receita"},{"id":"b","text":"Para desenhar uma casa"},{"id":"c","text":"Para descobrir como vivem os golfinhos"}],"correctAnswer":"c"},{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. O que fez depois de ler?","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q3","options":[{"id":"a","text":"Guardou uma concha"},{"id":"b","text":"Anotou duas perguntas"},{"id":"c","text":"Foi nadar"}],"correctAnswer":"b"},{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. A quem queria fazer as perguntas?","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q4","options":[{"id":"a","text":"À professora"},{"id":"b","text":"Ao carteiro"},{"id":"c","text":"Ao cozinheiro"}],"correctAnswer":"a"},{"type":"written","prompt":"Escreve uma pergunta que gostarias de fazer sobre os golfinhos.","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q5"},{"type":"written","prompt":"Resume o texto em duas frases, pelas tuas palavras.","topicId":"28c9285e-25d5-5c77-be6d-38952a45866b","id":"q6"}]}'::jsonb) on conflict(id) do nothing;
