insert into public.worksheet_versions(id,worksheet_id,version_number,school_year,content_json) values('70abb013-44c6-591b-82f1-917703c0cb09','b7b29e91-903b-5baa-911f-3c29f5d25b80',1,4,'{"instructions":"Lê com atenção e responde ao teu ritmo. Nas perguntas abertas, explica o teu raciocínio.","questions":[{"type":"multiple-choice","prompt":"Na frase «A Leonor leu um livro», qual é o verbo?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q1","options":[{"id":"a","text":"Leu"},{"id":"b","text":"Leonor"},{"id":"c","text":"Livro"}],"correctAnswer":"a"},{"type":"multiple-choice","prompt":"Qual é o plural de animal?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q2","options":[{"id":"a","text":"Animals"},{"id":"b","text":"Animales"},{"id":"c","text":"Animais"}],"correctAnswer":"c"},{"type":"multiple-choice","prompt":"Na expressão «mar azul», qual é o adjetivo?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q3","options":[{"id":"a","text":"Não existe adjetivo"},{"id":"b","text":"Azul"},{"id":"c","text":"Mar"}],"correctAnswer":"b"},{"type":"multiple-choice","prompt":"Qual é um sinónimo de contente?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q4","options":[{"id":"a","text":"Alegre"},{"id":"b","text":"Triste"},{"id":"c","text":"Cansado"}],"correctAnswer":"a"},{"type":"written","prompt":"Escreve uma frase com um nome, um verbo e um adjetivo.","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q5"},{"type":"written","prompt":"Transforma «O gato pequeno dorme» numa frase com o sujeito no plural.","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q6"}]}'::jsonb) on conflict(id) do nothing;
