insert into public.worksheet_versions(id,worksheet_id,version_number,school_year,content_json) values('c83f8976-2734-58b0-b62b-97a1491447e5','c284736a-b069-516b-b4d2-f747177393fe',1,4,'{"instructions":"Lê com atenção e responde ao teu ritmo. Nas perguntas abertas, explica o teu raciocínio.","questions":[{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. Qual era o assunto do livro procurado?","topicId":"c330dc97-2e16-5a26-a640-826b8befa08e","id":"q1","options":[{"id":"a","text":"Os oceanos"},{"id":"b","text":"As montanhas"},{"id":"c","text":"Os planetas"}],"correctAnswer":"a"},{"type":"multiple-choice","prompt":"Ao chegar à biblioteca, a Leonor procurou um livro sobre oceanos. Queria descobrir como vivem os golfinhos. Depois da leitura, anotou duas perguntas para fazer à professora. Por que procurou esse livro?","topicId":"c330dc97-2e16-5a26-a640-826b8befa08e","id":"q2","options":[{"id":"a","text":"Para aprender uma receita"},{"id":"b","text":"Para desenhar uma casa"},{"id":"c","text":"Para descobrir como vivem os golfinhos"}],"correctAnswer":"c"},{"type":"multiple-choice","prompt":"Na frase «A Leonor leu um livro», qual é o verbo?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q3","options":[{"id":"a","text":"Livro"},{"id":"b","text":"Leu"},{"id":"c","text":"Leonor"}],"correctAnswer":"b"},{"type":"multiple-choice","prompt":"Qual é o plural de animal?","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q4","options":[{"id":"a","text":"Animais"},{"id":"b","text":"Animals"},{"id":"c","text":"Animales"}],"correctAnswer":"a"},{"type":"written","prompt":"Escreve uma pergunta que gostarias de fazer sobre os golfinhos.","topicId":"c330dc97-2e16-5a26-a640-826b8befa08e","id":"q5"},{"type":"written","prompt":"Escreve uma frase com um nome, um verbo e um adjetivo.","topicId":"83bdfbef-ec2b-5b39-9876-4df13a8d582e","id":"q6"}]}'::jsonb) on conflict(id) do nothing;
